    s.append(u)

# STEP 2 of Kosaraju's Algorithm - DFS on the inverse graph
def dfs_second(u):
    if visited_inv[u]:
        return

    visited_inv[u] = True

    for neighbor in adj_inv[u]:
        dfs_second(neighbor)

    scc[u] = counter

