class TwoSatisfiability {
    const int MAX = 100000;

    // Data structures used to implement Kosaraju's
    // Algorithm Please refer:
    // https://www.geeksforgeeks.org/dsa/strongly-connected-components/
    static List<int>[] adj = new List<int>[ MAX ];
    static List<int>[] adjInv = new List<int>[ MAX ];
    static bool[] visited = new bool[MAX];
    static bool[] visitedInv = new bool[MAX];
    static Stack<int> s = new Stack<int>();

    // This array will store the SCC that the particular
    // node belongs to
    static int[] scc = new int[MAX];

    // Counter maintains the number of the SCC
    static int counter = 1;

    // Adds edges to form the original graph
    static void AddEdges(int a, int b) { adj[a].Add(b); }

    // Adds edges to form the inverse graph
    static void AddEdgesInverse(int a, int b)
    {
        adjInv[b].Add(a);
    }

    // STEP 1 of Kosaraju's Algorithm
    static void DfsFirst(int u)
    {
        if (visited[u])
            return;

        visited[u] = true;

        foreach(var v in adj[u]) DfsFirst(v);

        s.Push(u);
    }

    // STEP 2 of Kosaraju's Algorithm
    static void DfsSecond(int u)
    {
        if (visitedInv[u])
            return;

        visitedInv[u] = true;

        foreach(var v in adjInv[u]) DfsSecond(v);

        scc[u] = counter;
    }

    // Function to check 2-Satisfiability
    static void Is2Satisfiable(int n, int m, int[] a,
                               int[] b)
    {
        // Initialize the arrays
        for (int i = 0; i < MAX; i++) {
            adj[i] = new List<int>();
            adjInv[i] = new List<int>();
        }

        // Adding edges to the graph
        for (int i = 0; i < m; i++) {
            if (a[i] > 0 && b[i] > 0) {
                AddEdges(a[i] + n, b[i]);
                AddEdgesInverse(a[i] + n, b[i]);
                AddEdges(b[i] + n, a[i]);
                AddEdgesInverse(b[i] + n, a[i]);
            }
            else if (a[i] > 0 && b[i] < 0) {
                AddEdges(a[i] + n, n - b[i]);
                AddEdgesInverse(a[i] + n, n - b[i]);
                AddEdges(-b[i], a[i]);
                AddEdgesInverse(-b[i], a[i]);
            }
            else if (a[i] < 0 && b[i] > 0) {
                AddEdges(-a[i], b[i]);
                AddEdgesInverse(-a[i], b[i]);
                AddEdges(b[i] + n, n - a[i]);
                AddEdgesInverse(b[i] + n, n - a[i]);
            }
            else {
                AddEdges(-a[i], n - b[i]);
                AddEdgesInverse(-a[i], n - b[i]);
                AddEdges(-b[i], n - a[i]);
                AddEdgesInverse(-b[i], n - a[i]);
            }
        }

        // STEP 1 of Kosaraju's Algorithm which traverses
        // the original graph
        for (int i = 1; i <= 2 * n; i++)
            if (!visited[i])
                DfsFirst(i);

        // STEP 2 of Kosaraju's Algorithm which traverses
        // the inverse graph. After this, array scc[] stores
        // the corresponding value
        while (s.Count > 0) {
            int node = s.Pop();

            if (!visitedInv[node]) {
                DfsSecond(node);
                counter++;
            }
        }

        for (int i = 1; i <= n; i++) {
            // For any 2 variables x and -x lie in the same
            // SCC
            if (scc[i] == scc[i + n]) {
                Console.WriteLine(
                    "The given expression is unsatisfiable.");
                return;
            }
        }

        // No such variables x and -x exist which lie in the
        // same SCC
        Console.WriteLine(
            "The given expression is satisfiable.");
    }

    // Driver function to test above functions
    static void Main()
    {
        // n is the number of variables
        // 2n is the total number of nodes
        // m is the number of clauses
        int n = 5, m = 7;

        // Each clause is of the form a or b
        // For m clauses, we have a[m], b[m] representing
        // a[i] or b[i]

        // Note:
        // 1 <= x <= N for an uncomplemented variable x
        // -N <= x <= -1 for a complemented variable x
        // -x is the complement of a variable x

        // The CNF being handled is:
        // '+' implies 'OR' and '*' implies 'AND'
        // (x1+x2)*(x2’+x3)*(x1’+x2’)*(x3+x4)*(x3’+x5)*
        // (x4’+x5’)*(x3’+x4)
